import{_ as i,o as n,c as a,a2 as t}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Invoicing & Subscription Engine","description":"","frontmatter":{},"headers":[],"relativePath":"admin/invoicing.md","filePath":"admin/invoicing.md"}'),o={name:"admin/invoicing.md"};function s(r,e,c,l,d,u){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="invoicing-subscription-engine" tabindex="-1">Invoicing &amp; Subscription Engine <a class="header-anchor" href="#invoicing-subscription-engine" aria-label="Permalink to &quot;Invoicing &amp; Subscription Engine&quot;">​</a></h1><p>FOSSBilling features an automated billing engine that handles one-time charges, recurring subscriptions, tax calculations, dynamic promos, and overdue suspensions.</p><hr><h2 id="📅-subscription-lifecycle-automated-worker" tabindex="-1">📅 Subscription Lifecycle &amp; Automated Worker <a class="header-anchor" href="#📅-subscription-lifecycle-automated-worker" aria-label="Permalink to &quot;📅 Subscription Lifecycle &amp; Automated Worker&quot;">​</a></h2><ol><li><strong>Advance Invoicing (14 Days Prior):</strong><ul><li>The background scheduler daemon (<code>cmd/worker</code>) scans active subscriptions and generates upcoming renewal invoices 14 days before the service due date.</li></ul></li><li><strong>Invoice Reminder Notifications:</strong><ul><li>Automated email templates notify clients of pending due dates and provide direct 1-click payment links.</li></ul></li><li><strong>Automatic Settlement on Balance:</strong><ul><li>If a client has sufficient credit in their balance, the invoice is settled automatically upon generation.</li></ul></li><li><strong>Grace Period &amp; Suspension (7 Days Post Due Date):</strong><ul><li>If an invoice remains unpaid 7 days past the due date, the worker marks the service as <code>suspended</code> and executes remote suspension via the assigned server provisioner (e.g., WHM/Plesk API).</li></ul></li><li><strong>Instant Reactivation upon Payment:</strong><ul><li>As soon as the overdue invoice is paid, the event listener triggers automatic unsuspension.</li></ul></li></ol><hr><h2 id="🧾-pdf-invoices-receipts" tabindex="-1">🧾 PDF Invoices &amp; Receipts <a class="header-anchor" href="#🧾-pdf-invoices-receipts" aria-label="Permalink to &quot;🧾 PDF Invoices &amp; Receipts&quot;">​</a></h2><ul><li>Invoices feature downloadable PDF generation powered by <code>pkg/pdf</code>.</li><li>Customizable company headers, logos, tax identification numbers, and terms of service.</li></ul>',8)])])}const g=i(o,[["render",s]]);export{m as __pageData,g as default};
